(function(){
 'use strict';const $=id=>document.getElementById(id),{n,download,sourceBox}=PlatformUI,M=PlatformModel,data=window.PRACTICE_CONTENT;let state=M.emptyPractice(),saved=M.emptyPractice(),lastRaw=null,writable=true,utterance=null;
 function warning(t){$('practiceStorageNote').hidden=false;$('practiceStorageNote').textContent=t;}
 try{lastRaw=localStorage.getItem(M.PRACTICE);if(lastRaw)state=M.cleanPractice(JSON.parse(lastRaw));saved=structuredClone(state);}catch{writable=false;warning('Не удалось прочитать сохранение. Исходные данные не изменены. Работа в памяти: скачайте эту практику перед закрытием.');if(lastRaw!==null){const original=n('button','Скачать исходную запись','quiet outlined');original.type='button';original.onclick=()=>download('psycholibrary-practice-original.json',lastRaw);$('practiceStorageNote').append(original);}}
 function save(){if(!writable)return;try{const raw=localStorage.getItem(M.PRACTICE);if(raw!==lastRaw&&raw){const latest=M.cleanPractice(JSON.parse(raw));for(const field of ['cases','drafts','completed'])for(const id of new Set([...Object.keys(saved[field]),...Object.keys(state[field])]))if(JSON.stringify(saved[field][id])!==JSON.stringify(state[field][id])){if(Object.hasOwn(state[field],id))latest[field][id]=state[field][id];else delete latest[field][id];}for(const field of ['cases','drafts','completed']){for(const id of Object.keys(state[field]))if(!Object.hasOwn(latest[field],id))delete state[field][id];for(const [id,value]of Object.entries(latest[field]))if(JSON.stringify(state[field][id])===JSON.stringify(saved[field][id]))state[field][id]=value;}}lastRaw=JSON.stringify(state);localStorage.setItem(M.PRACTICE,lastRaw);saved=structuredClone(state);}catch{writable=false;warning('Сохранение недоступно. Ответы остаются в этой вкладке; скачайте практику перед закрытием.');}}
 const status=t=>$('practiceStatus').textContent=t;
 function button(text,handler,cls='quiet outlined'){const b=n('button',text,cls);b.type='button';b.onclick=handler;return b;}
 function select(items,chosen,change){const s=n('select');s.setAttribute('aria-label','Учебная ситуация');for(const x of items){const o=n('option',x.title);o.value=x.id;s.append(o);}s.value=chosen;s.onchange=()=>change(s.value);return s;}
 function linkFor(tab,id){location.hash=tab+'&item='+id;}
 function choiceGroup(title,options,value,callback,multiple=false){const f=n('fieldset',undefined,'platform-card');f.append(n('legend',title));for(const [id,text]of options){const label=n('label'),input=n('input');input.type=multiple?'checkbox':'radio';input.name=title;input.value=id;input.checked=multiple?(value||[]).includes(id):value===id;input.onchange=()=>callback(multiple?[...f.querySelectorAll('input:checked')].map(x=>x.value):id);label.append(input,document.createTextNode(' '+text));f.append(label);}return f;}
 function record(key){const r=state.cases[key]||={};for(const [k,v]of Object.entries({initial:'',revealed:[],final:'',why:'',next:[],feedback:false}))if(r[k]===undefined)r[k]=v;return r;}
 function renderCase(c,mode){const key=(mode==='hypotheses'?'hypothesis-':'case-')+c.id,r=record(key),panel=$('practicePanel');panel.append(select(data.cases,c.id,id=>linkFor(mode,id)),n('h2',c.title),n('p',c.opening,'platform-lead'));
  panel.append(choiceGroup('Первоначальная гипотеза',c.hypotheses.map((h,i)=>[String(i),h]),r.initial,v=>{r.initial=v;save();render();}));
  const history=n('section',undefined,'platform-card');history.append(n('h3','Какие сведения запросить?'),n('p','Сначала зафиксируйте предположение. Новые данные могут поддержать его, ослабить или оставить вопрос открытым.'));
  for(const [id,label,text,reason]of c.evidence){const reveal=button(label,()=>{if(!r.revealed.includes(id))r.revealed.push(id);save();render();});reveal.disabled=r.initial===''||r.revealed.includes(id);history.append(reveal);if(r.revealed.includes(id)){const box=n('div',undefined,'platform-note');box.append(n('p',text),n('p',reason,'platform-meta'));history.append(box);}}panel.append(history);
  if(r.revealed.length){panel.append(n('p','Собрано направлений сведений: '+r.revealed.length+' из '+c.evidence.length+'. Это не оценка полноты реального обследования.','platform-meta'));panel.append(choiceGroup('Гипотеза после новых данных',c.hypotheses.map((h,i)=>[String(i),h]),r.final,v=>{r.final=v;save();}));
   const label=n('label','Что изменило ваше мнение? Какие сведения ещё нужны?'),why=n('textarea');why.maxLength=10000;why.value=r.why;why.placeholder='Обоснуйте ход рассуждений на данных вымышленного случая.';why.oninput=()=>{r.why=why.value;save();};label.append(why);panel.append(label);
   panel.append(choiceGroup('Какие следующие шаги обоснованы? Можно несколько.',c.next,r.next,v=>{r.next=v;save();},true));
   panel.append(button('Сопоставить с разбором',()=>{if(r.revealed.length<3||r.final===''||r.why.trim().length<20||!r.next.length){status('Соберите минимум три направления сведений, выберите гипотезу и следующий шаг, объясните решение минимум в 20 символах.');return;}r.feedback=true;state.completed[key]=Date.now();save();render();status('Разбор открыт. Свободный текст оценивается вами по рубрике; экспертная оценка не проводится.');},'primary'));
  }
  if(r.feedback){const fb=n('section',undefined,'platform-card');fb.append(n('h3','Разбор рассуждения'),n('p',c.feedback));const missed=c.priority.filter(id=>!r.revealed.includes(id));fb.append(n('p',missed.length?'Не исследованы важные направления: '+missed.map(id=>c.evidence.find(e=>e[0]===id)[1]).join('; '):'Все выделенные в сценарии важные направления сведений открыты.'));const unsafe=r.next.filter(id=>!c.reasonable.includes(id));fb.append(n('p',unsafe.length?'Пересмотрите выбранный шаг: '+unsafe.map(id=>c.next.find(x=>x[0]===id)[1]).join('; '):'Выбранные шаги согласуются с логикой учебного разбора.'));fb.append(n('p',r.initial===r.final?'Вы сохранили гипотезу. Проверьте, какие данные могли бы её опровергнуть.':'Вы изменили гипотезу. Назовите данные, из-за которых изменился вывод.'));fb.append(sourceBox(c.sources));panel.append(fb);}
  panel.append(button('Начать этот сценарий заново',()=>{state.cases[key]={initial:'',revealed:[],final:'',why:'',next:[],feedback:false};delete state.completed[key];save();render();}));
 }
 function renderAtlas(item){const panel=$('practicePanel');panel.append(select(data.atlas,item.id,id=>linkFor('atlas',id)),n('h2',item.title));const grid=n('div',undefined,'platform-comparison');item.features.forEach((f,i)=>{const box=n('div');box.append(n('strong',item.labels?.[i]||item.topics[i]||'Область сравнения'),n('p',f));grid.append(box);});panel.append(grid,n('blockquote',item.quote,'platform-note'),n('p','Что уточнить: '+item.question));const key='atlas-'+item.id;if(state.completed[key]){panel.append(n('p',item.answer),sourceBox(item.sources));}else panel.append(button('Открыть разбор',()=>{state.completed[key]=Date.now();save();render();},'primary'));}
 function stopAudio(){if('speechSynthesis'in window)speechSynthesis.cancel();utterance=null;}
 function renderAudio(item){const panel=$('practicePanel');panel.append(select(data.audio,item.id,id=>{stopAudio();linkFor('audio',id);}),n('h2',item.title),n('p','Синтезированный учебный голос читает вымышленный рассказ. Оценивайте содержание переживания: тембр, темп и интонация синтеза не являются образцом клинической речи.','platform-note'));
  const controls=n('div',undefined,'platform-actions');controls.append(button('▶ Прослушать',()=>{if(!('speechSynthesis'in window)){status('Синтез речи недоступен; откройте текст сценария.');return;}stopAudio();const voices=speechSynthesis.getVoices(),voice=voices.find(v=>v.lang.toLowerCase().startsWith('ru'));if(!voice){status('Русский голос не найден. Откройте текст сценария или установите голос в настройках устройства.');return;}utterance=new SpeechSynthesisUtterance(item.script);utterance.lang='ru-RU';utterance.voice=voice;utterance.rate=1;utterance.onerror=()=>status('Озвучивание недоступно. Текст сценария остаётся доступным.');speechSynthesis.speak(utterance);},'primary'),button('Пауза / продолжить',()=>{if(!('speechSynthesis'in window))return;speechSynthesis.paused?speechSynthesis.resume():speechSynthesis.pause();}),button('Стоп',stopAudio));panel.append(controls);const transcript=n('details',undefined,'platform-details');transcript.append(n('summary','Текст сценария'),n('p',item.script));panel.append(transcript,n('p',item.prompt));
  const key='audio-'+item.id,label=n('label','Ваше описание и уточняющие вопросы'),text=n('textarea');text.maxLength=10000;text.value=state.drafts[key]||'';text.oninput=()=>{state.drafts[key]=text.value;save();};label.append(text);panel.append(label,button('Сопоставить наблюдения',()=>{state.completed[key]=Date.now();save();render();},'primary'));
  if(state.completed[key]){const box=n('section',undefined,'platform-card'),ul=n('ul');item.observations.forEach(x=>ul.append(n('li',x)));box.append(n('h3','Ориентиры описания'),ul,n('p',item.feedback),sourceBox(item.sources));panel.append(box);}
 }
 function renderTimeline(item){const panel=$('practicePanel'),key='timeline-'+item.id,r=record(key);panel.append(select(data.timelines,item.id,id=>linkFor('timeline',id)),n('h2',item.title),n('p','Вымышленная временная линия. Сопоставьте события и выделите интересующий отрезок; временная связь сама по себе не доказывает причину.'));const wrap=n('div',undefined,'platform-timeline');wrap.tabIndex=0;wrap.setAttribute('role','region');wrap.setAttribute('aria-label','Временная шкала, доступна горизонтальная прокрутка');const table=n('table'),head=n('thead'),tr=n('tr');tr.append(n('th','Область'));item.periods.forEach(p=>tr.append(n('th',p)));head.append(tr);table.append(head);const body=n('tbody');item.lanes.forEach(row=>{const tr=n('tr');row.forEach((cell,i)=>{const td=n(i?'td':'th',cell);if(!i)td.scope='row';tr.append(td);});body.append(tr);});table.append(body);wrap.append(table);panel.append(wrap,choiceGroup(item.question,item.periods.map((p,i)=>[String(i),p]),r.next,v=>{r.next=v;save();},true),button('Открыть разбор',()=>{if(!r.next.length){status('Выберите отрезок на временной шкале.');return;}r.feedback=true;state.completed[key]=Date.now();save();render();},'primary'));if(r.feedback){const same=r.next.length===item.answers.length&&r.next.every(x=>item.answers.includes(Number(x)));panel.append(n('p',same?'Выделен ожидаемый в задаче отрезок.':'Сопоставьте выбор с отрезками: '+item.answers.map(i=>item.periods[i]).join(', ')),n('p',item.feedback),sourceBox(item.sources));}}
 function renderExplain(item){const panel=$('practicePanel'),key='explain-'+item.id;panel.append(select(data.explain,item.id,id=>linkFor('explain',id)),n('h2',item.title),n('p',item.situation,'platform-note'));const label=n('label','Как бы вы ответили? Без сведений о реальных пациентах.'),text=n('textarea');text.maxLength=10000;text.value=state.drafts[key]||'';text.placeholder='Сформулируйте объяснение простыми словами.';text.oninput=()=>{state.drafts[key]=text.value;save();};label.append(text);panel.append(label,button('Сопоставить с примером и рубрикой',()=>{if(text.value.trim().length<40){status('Напишите свой вариант минимум в 40 символах, затем сопоставьте с примером.');return;}state.completed[key]=Date.now();save();render();},'primary'));if(state.completed[key]){panel.append(n('h3','Один из вариантов объяснения'),n('p',item.example,'platform-card'));const f=n('fieldset',undefined,'platform-card');f.append(n('legend','Самопроверка: что есть в вашем ответе?'));const chosen=state.cases[key]?.next||[];data.rubric.forEach((t,i)=>{const label=n('label'),input=n('input');input.type='checkbox';input.value=i;input.checked=chosen.includes(String(i));input.onchange=()=>{state.cases[key]||={next:[]};state.cases[key].next=[...f.querySelectorAll('input:checked')].map(x=>x.value);save();};label.append(input,document.createTextNode(' '+t));f.append(label);});panel.append(f,n('p','Это ваша оценка по рубрике, а не автоматическое заключение о качестве консультации.','platform-meta'),sourceBox(item.sources));}}
 function render(){stopAudio();const [tab='cases',...rest]=location.hash.slice(1).split('&'),params=new URLSearchParams(rest.join('&')),groups={cases:'cases',hypotheses:'cases',atlas:'atlas',audio:'audio',timeline:'timelines',explain:'explain'},group=groups[tab];if(!group){location.hash='cases';return;}for(const a of document.querySelectorAll('.platform-tabs a')){if(a.hash==='#'+tab)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');}const item=data[group].find(x=>x.id===params.get('item'))||data[group][0];$('practicePanel').replaceChildren();status('');if(tab==='cases'||tab==='hypotheses')renderCase(item,tab);else if(tab==='atlas')renderAtlas(item);else if(tab==='audio')renderAudio(item);else if(tab==='timeline')renderTimeline(item);else renderExplain(item);}
 $('exportPractice').onclick=()=>download('psycholibrary-practice-backup.json',{format:'psycholibrary-practice-backup',schemaVersion:1,state});window.addEventListener('hashchange',render);document.addEventListener('visibilitychange',()=>{if(document.hidden)stopAudio();});window.addEventListener('pagehide',stopAudio);window.addEventListener('storage',e=>{if(e.key===M.PRACTICE&&e.newValue!==lastRaw)status('Практика изменена в другой вкладке. При сохранении независимые записи будут объединены.');});render();
})();
